-- Learning dataset seed data.
--
-- GENERATED by tools/generate_dataset.py. Deterministic: regenerating
-- produces a byte-identical file, which is what lets the expected outputs
-- recorded against every lesson example stay valid.
--
-- This is NOT a Flyway migration. It is executed by DatasetResetService,
-- both to populate an empty database at startup and to serve the Reset
-- Dataset button, so the two paths cannot diverge.
--
-- TRUNCATE ... RESTART IDENTITY CASCADE first, so the file is re-runnable
-- and leaves no trace of whatever the previous state was.

truncate table learning.exam_scores, learning.contacts, learning.daily_sales, learning.account_status_history, learning.user_activity, learning.payments, learning.order_items, learning.orders, learning.customers, learning.products, learning.categories, learning.employee_projects, learning.projects, learning.employees, learning.departments restart identity cascade;
truncate table learning_alt.exam_scores, learning_alt.contacts, learning_alt.daily_sales, learning_alt.account_status_history, learning_alt.user_activity, learning_alt.payments, learning_alt.order_items, learning_alt.orders, learning_alt.customers, learning_alt.products, learning_alt.categories, learning_alt.employee_projects, learning_alt.projects, learning_alt.employees, learning_alt.departments restart identity cascade;

